CREATE OR REPLACE FUNCTION private.keep_bits_off()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  new.bits_store_enabled := false;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION private.touch_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin
  new.updated_at = now();
  return new;
end;
$function$
